import fs from 'node:fs/promises';
import { createNativeCdpBrowserDriver } from './src/execution/native-cdp-browser-driver.mjs';
import { createBrowserComputerReceptor } from './src/execution/browser-computer-receptor.mjs';

const driver=createNativeCdpBrowserDriver();
const receptor=createBrowserComputerReceptor({driver,name:'mondayid-native-browser-live'});
const html='<title>Monday Live</title><input id="seed"><div id="receipt">initial</div>';
const action={
  domain:'host',
  effect:'execute and independently verify a real browser effect through the Monday-owned CDP driver',
  routeCandidate:{
    kind:'browser',
    steps:[
      {type:'open',url:'data:text/html,'+encodeURIComponent(html)},
      {type:'fill',selector:'#seed',value:'Monday'},
      {type:'evaluate',expression:'document.querySelector("#receipt").textContent=document.querySelector("#seed").value+"-browser-live-ok"'}
    ],
    verification:{
      probe:{type:'text',selector:'#receipt'},
      acceptance:{equals:'Monday-browser-live-ok',ok:true}
    }
  }
};
try {
  const result=await receptor.execute(action);
  const verification=await receptor.verify(result,action);
  const proof={resultOk:result.ok===true,verification};
  await fs.writeFile('native-browser-live.json',JSON.stringify(proof));
  if (!verification.ok) process.exitCode=2;
} finally {
  await driver.close();
}
